/******************************************************************************
 * HOURLY BID ADJUSTMENT SCRIPT
 *
 * Generated by PPC.io Script Engine
 * https://ppc.io
 *
 * Purpose: Analyze hourly performance and apply optimal bid adjustments
 * Author:  PPC.io
 * Version: 1.0
 * Updated: 2025-01-14
 *
 * SETUP INSTRUCTIONS:
 * 1. Set SPREADSHEET_URL to 'CREATE_NEW' or paste existing URL
 * 2. Set TARGET_CPA or TARGET_ROAS for your account
 * 3. Run in Preview mode first (DRY_RUN = true)
 * 4. Review proposed changes before enabling
 * 5. Schedule: Weekly to adjust, Daily to monitor
 *
 * USE CASE: "What hours should I bid higher/lower? How much can I improve CPA with hourly adjustments?"
 *
 * HOW IT WORKS:
 * - Analyzes performance by hour of day and day of week
 * - Calculates optimal bid modifiers based on CPA/ROAS
 * - Hours performing better than target get positive modifiers
 * - Hours performing worse get negative modifiers
 * - Applies to campaign ad schedules
 *
 * OUTPUTS:
 * - 1. Summary: Campaigns optimized, expected improvement
 * - 2. Hourly Performance: Heat map of performance by hour
 * - 3. Proposed Modifiers: What changes would be made
 * - 4. Applied Changes: Log of changes made (if not DRY_RUN)
 *
 * CHANGELOG:
 * v1.0 - Initial release with GAQL-first architecture
 *
 ******************************************************************************/

/******************************************************************************
 * CONFIGURATION - Adjust these values for your account
 ******************************************************************************/
var CONFIG = {
  // ═══════════════════════════════════════════════════════════════════════════
  // OUTPUT SETTINGS
  // ═══════════════════════════════════════════════════════════════════════════
  SPREADSHEET_URL: 'CREATE_NEW',  // Or paste existing spreadsheet URL
  EMAIL_RECIPIENTS: [],           // ['email@example.com']
  SLACK_WEBHOOK_URL: '',          // Slack incoming webhook URL

  // ═══════════════════════════════════════════════════════════════════════════
  // DATE RANGE FOR ANALYSIS
  // ═══════════════════════════════════════════════════════════════════════════
  DATE_RANGE: 'LAST_30_DAYS',     // Use enough data for reliable hourly trends

  // ═══════════════════════════════════════════════════════════════════════════
  // FILTERS
  // ═══════════════════════════════════════════════════════════════════════════
  CAMPAIGN_NAME_CONTAINS: '',     // Filter to campaigns containing this
  CAMPAIGN_NAME_EXCLUDES: '',     // Exclude campaigns containing this
  INCLUDE_PAUSED: false,          // Include paused campaigns
  CAMPAIGN_TYPES: ['SEARCH'],     // Campaign types to optimize

  // ═══════════════════════════════════════════════════════════════════════════
  // PERFORMANCE TARGETS (set ONE of these)
  // ═══════════════════════════════════════════════════════════════════════════
  TARGET_CPA: 50,                 // Target cost per acquisition (set to 0 to use ROAS)
  TARGET_ROAS: 0,                 // Target return on ad spend (set to 0 to use CPA)

  // ═══════════════════════════════════════════════════════════════════════════
  // BID MODIFIER SETTINGS
  // ═══════════════════════════════════════════════════════════════════════════
  MAX_BID_INCREASE: 0.50,         // Maximum bid increase (+50%)
  MAX_BID_DECREASE: -0.50,        // Maximum bid decrease (-50%)
  MIN_CONVERSIONS_FOR_ADJUSTMENT: 5, // Minimum conversions in hour to trust data
  MIN_CLICKS_FOR_ADJUSTMENT: 20,  // Minimum clicks in hour to trust data

  // Modifier calculation sensitivity
  AGGRESSIVE_MODE: false,         // true = full calculated modifiers, false = dampened

  // ═══════════════════════════════════════════════════════════════════════════
  // AUTOMATION SETTINGS
  // ═══════════════════════════════════════════════════════════════════════════
  DRY_RUN: true,                  // CRITICAL: Set false to apply changes
  APPLY_AD_SCHEDULES: true,       // Apply calculated schedules to campaigns
  REMOVE_EXISTING_SCHEDULES: false, // Remove existing ad schedules before applying

  // ═══════════════════════════════════════════════════════════════════════════
  // EXECUTION SETTINGS
  // ═══════════════════════════════════════════════════════════════════════════
  LOG_LEVEL: 'INFO',              // DEBUG, INFO, WARN, ERROR
  TIME_LIMIT_MINUTES: 25,         // Exit gracefully before this
  BATCH_SIZE: 500                 // Rows per spreadsheet write
};

// Day names for schedules
var DAYS = ['SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'];
var DAY_ABBREV = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

/******************************************************************************
 * MAIN EXECUTION
 ******************************************************************************/
function main() {
  var startTime = new Date();
  log('INFO', 'Hourly Bid Adjustment Script started: ' + startTime.toISOString());
  log('INFO', 'Mode: ' + (CONFIG.DRY_RUN ? 'DRY RUN' : 'LIVE'));

  try {
    var ss = initializeSpreadsheet();
    var results = analyzeHourlyPerformance(startTime);

    if (CONFIG.APPLY_AD_SCHEDULES && !CONFIG.DRY_RUN) {
      applyBidAdjustments(results);
    }

    writeAllSheets(ss, results);
    sendNotifications(results, ss.getUrl(), startTime);
    logSummary(results, startTime);

  } catch (error) {
    handleFatalError(error, startTime);
  }
}

/******************************************************************************
 * DATA COLLECTION & ANALYSIS
 ******************************************************************************/
function analyzeHourlyPerformance(startTime) {
  var results = {
    campaigns: [],
    hourlyData: [],           // Performance by hour
    dayHourData: [],          // Performance by day and hour
    proposedModifiers: [],    // Calculated modifiers
    appliedChanges: [],       // Changes made (if not DRY_RUN)
    heatmapData: [],          // For visualization
    summary: {
      totalCampaigns: 0,
      campaignsOptimized: 0,
      totalConversions: 0,
      totalCost: 0,
      currentCPA: 0,
      currentROAS: 0,
      estimatedCPAImprovement: 0,
      estimatedROASImprovement: 0,
      bestHours: [],
      worstHours: [],
      modifiersApplied: 0
    }
  };

  // Collect hourly performance data
  log('INFO', 'Collecting hourly performance data...');
  collectHourlyData(results, startTime);

  // Calculate optimal modifiers
  log('INFO', 'Calculating optimal bid modifiers...');
  calculateModifiers(results);

  // Identify best/worst hours
  identifyBestWorstHours(results);

  return results;
}

function collectHourlyData(results, startTime) {
  var hourlyMap = {}; // hour -> aggregated data
  var dayHourMap = {}; // day|hour -> aggregated data
  var campaignHourMap = {}; // campaignId|hour -> data

  try {
    // Build campaign type filter
    var typeFilter = CONFIG.CAMPAIGN_TYPES.map(function(t) {
      return '"' + t + '"';
    }).join(', ');

    var query = 'SELECT ' +
      'campaign.id, ' +
      'campaign.name, ' +
      'segments.hour, ' +
      'segments.day_of_week, ' +
      'metrics.impressions, ' +
      'metrics.clicks, ' +
      'metrics.cost_micros, ' +
      'metrics.conversions, ' +
      'metrics.conversions_value ' +
      'FROM campaign ' +
      'WHERE segments.date DURING ' + CONFIG.DATE_RANGE + ' ' +
      'AND campaign.advertising_channel_type IN (' + typeFilter + ')';

    if (!CONFIG.INCLUDE_PAUSED) {
      query += ' AND campaign.status = "ENABLED"';
    }

    var rows = AdsApp.search(query);
    var count = 0;
    var campaignSet = {};

    while (rows.hasNext()) {
      var row = rows.next();
      var campaignName = row['campaign.name'];

      if (!passesCampaignFilter(campaignName)) continue;

      var campaignId = row['campaign.id'];
      var hour = parseInt(row['segments.hour'], 10);
      var dayOfWeek = row['segments.day_of_week'] || '';

      var impressions = parseInt(row['metrics.impressions'] || 0, 10);
      var clicks = parseInt(row['metrics.clicks'] || 0, 10);
      var cost = parseInt(row['metrics.cost_micros'] || 0, 10) / 1000000;
      var conversions = parseFloat(row['metrics.conversions'] || 0);
      var convValue = parseFloat(row['metrics.conversions_value'] || 0);

      // Track campaigns
      if (!campaignSet[campaignId]) {
        campaignSet[campaignId] = {
          id: campaignId,
          name: campaignName,
          totalCost: 0,
          totalConversions: 0,
          totalRevenue: 0
        };
      }
      campaignSet[campaignId].totalCost += cost;
      campaignSet[campaignId].totalConversions += conversions;
      campaignSet[campaignId].totalRevenue += convValue;

      // Aggregate by hour (account level)
      if (!hourlyMap[hour]) {
        hourlyMap[hour] = createEmptyBucket();
      }
      addToBucket(hourlyMap[hour], impressions, clicks, cost, conversions, convValue);

      // Aggregate by day + hour
      var dayHourKey = dayOfWeek + '|' + hour;
      if (!dayHourMap[dayHourKey]) {
        dayHourMap[dayHourKey] = createEmptyBucket();
        dayHourMap[dayHourKey].day = dayOfWeek;
        dayHourMap[dayHourKey].hour = hour;
      }
      addToBucket(dayHourMap[dayHourKey], impressions, clicks, cost, conversions, convValue);

      // Aggregate by campaign + hour
      var campHourKey = campaignId + '|' + hour;
      if (!campaignHourMap[campHourKey]) {
        campaignHourMap[campHourKey] = createEmptyBucket();
        campaignHourMap[campHourKey].campaignId = campaignId;
        campaignHourMap[campHourKey].campaignName = campaignName;
        campaignHourMap[campHourKey].hour = hour;
      }
      addToBucket(campaignHourMap[campHourKey], impressions, clicks, cost, conversions, convValue);

      count++;
      if (count % 1000 === 0) {
        checkTimeLimit(startTime);
      }
    }

    // Convert to arrays
    for (var h = 0; h < 24; h++) {
      var hourData = hourlyMap[h] || createEmptyBucket();
      hourData.hour = h;
      hourData.hourLabel = formatHour(h);
      calculateMetrics(hourData);
      results.hourlyData.push(hourData);
    }

    for (var dhKey in dayHourMap) {
      calculateMetrics(dayHourMap[dhKey]);
      results.dayHourData.push(dayHourMap[dhKey]);
    }

    // Convert campaigns
    for (var cId in campaignSet) {
      results.campaigns.push(campaignSet[cId]);
    }

    // Calculate totals
    results.summary.totalCampaigns = results.campaigns.length;
    results.summary.totalCost = results.campaigns.reduce(function(sum, c) { return sum + c.totalCost; }, 0);
    results.summary.totalConversions = results.campaigns.reduce(function(sum, c) { return sum + c.totalConversions; }, 0);

    if (results.summary.totalConversions > 0) {
      results.summary.currentCPA = results.summary.totalCost / results.summary.totalConversions;
    }
    if (results.summary.totalCost > 0) {
      var totalRevenue = results.campaigns.reduce(function(sum, c) { return sum + c.totalRevenue; }, 0);
      results.summary.currentROAS = totalRevenue / results.summary.totalCost;
    }

    log('INFO', 'Collected data for ' + results.summary.totalCampaigns + ' campaigns');

  } catch (e) {
    log('WARN', 'GAQL hourly fetch failed: ' + e.message);
    collectHourlyDataFallback(results, startTime);
  }
}

function collectHourlyDataFallback(results, startTime) {
  // Simplified fallback - uses campaign stats without hourly breakdown
  log('WARN', 'Fallback does not support hourly breakdown. Running in report-only mode.');

  var campaigns = AdsApp.campaigns()
    .withCondition('AdvertisingChannelType IN [' + CONFIG.CAMPAIGN_TYPES.join(', ') + ']');

  if (!CONFIG.INCLUDE_PAUSED) {
    campaigns = campaigns.withCondition('Status = ENABLED');
  }

  var iterator = campaigns.get();

  while (iterator.hasNext()) {
    var campaign = iterator.next();
    var name = campaign.getName();

    if (!passesCampaignFilter(name)) continue;

    var stats = campaign.getStatsFor(CONFIG.DATE_RANGE);

    results.campaigns.push({
      id: campaign.getId(),
      name: name,
      totalCost: stats.getCost(),
      totalConversions: stats.getConversions(),
      totalRevenue: stats.getConversionValue()
    });
  }

  results.summary.totalCampaigns = results.campaigns.length;
}

function createEmptyBucket() {
  return {
    impressions: 0,
    clicks: 0,
    cost: 0,
    conversions: 0,
    convValue: 0
  };
}

function addToBucket(bucket, impressions, clicks, cost, conversions, convValue) {
  bucket.impressions += impressions;
  bucket.clicks += clicks;
  bucket.cost += cost;
  bucket.conversions += conversions;
  bucket.convValue += convValue;
}

function calculateMetrics(bucket) {
  bucket.ctr = bucket.impressions > 0 ? bucket.clicks / bucket.impressions : 0;
  bucket.convRate = bucket.clicks > 0 ? bucket.conversions / bucket.clicks : 0;
  bucket.cpa = bucket.conversions > 0 ? bucket.cost / bucket.conversions : null;
  bucket.roas = bucket.cost > 0 ? bucket.convValue / bucket.cost : 0;
}

/******************************************************************************
 * MODIFIER CALCULATION
 ******************************************************************************/
function calculateModifiers(results) {
  var target = CONFIG.TARGET_CPA > 0 ? 'CPA' : 'ROAS';
  var targetValue = CONFIG.TARGET_CPA > 0 ? CONFIG.TARGET_CPA : CONFIG.TARGET_ROAS;

  // Calculate account average for comparison if no target set
  if (targetValue === 0) {
    if (target === 'CPA') {
      targetValue = results.summary.currentCPA || 50;
    } else {
      targetValue = results.summary.currentROAS || 3;
    }
    log('INFO', 'No target set, using account average: ' + targetValue.toFixed(2));
  }

  var totalEstimatedImprovement = 0;
  var improvementWeight = 0;

  for (var h = 0; h < 24; h++) {
    var hourData = results.hourlyData[h];

    if (!hourData) continue;

    var modifier = 0;
    var reason = '';
    var canAdjust = true;

    // Check if we have enough data
    if (hourData.conversions < CONFIG.MIN_CONVERSIONS_FOR_ADJUSTMENT &&
        hourData.clicks < CONFIG.MIN_CLICKS_FOR_ADJUSTMENT) {
      canAdjust = false;
      reason = 'Insufficient data';
      modifier = 0;
    } else if (target === 'CPA' && hourData.cpa !== null) {
      // CPA-based calculation
      // If hour CPA is better (lower) than target, increase bids
      // If hour CPA is worse (higher) than target, decrease bids
      var cpaRatio = targetValue / hourData.cpa;

      if (hourData.cpa < targetValue) {
        // Good hour - CPA below target
        modifier = Math.min(cpaRatio - 1, CONFIG.MAX_BID_INCREASE);
        reason = 'CPA $' + hourData.cpa.toFixed(2) + ' below target $' + targetValue.toFixed(2);
      } else {
        // Bad hour - CPA above target
        modifier = Math.max(cpaRatio - 1, CONFIG.MAX_BID_DECREASE);
        reason = 'CPA $' + hourData.cpa.toFixed(2) + ' above target $' + targetValue.toFixed(2);
      }

    } else if (target === 'ROAS' && hourData.roas > 0) {
      // ROAS-based calculation
      // If hour ROAS is better (higher) than target, increase bids
      var roasRatio = hourData.roas / targetValue;

      if (hourData.roas > targetValue) {
        modifier = Math.min(roasRatio - 1, CONFIG.MAX_BID_INCREASE);
        reason = 'ROAS ' + hourData.roas.toFixed(2) + 'x above target ' + targetValue.toFixed(2) + 'x';
      } else {
        modifier = Math.max(roasRatio - 1, CONFIG.MAX_BID_DECREASE);
        reason = 'ROAS ' + hourData.roas.toFixed(2) + 'x below target ' + targetValue.toFixed(2) + 'x';
      }
    } else {
      canAdjust = false;
      reason = 'No conversion data';
      modifier = 0;
    }

    // Apply dampening if not aggressive mode
    if (!CONFIG.AGGRESSIVE_MODE && modifier !== 0) {
      modifier = modifier * 0.5; // Dampen by 50%
    }

    // Round modifier
    modifier = Math.round(modifier * 100) / 100;

    // Estimate improvement
    var estimatedImprovement = 0;
    if (modifier !== 0 && hourData.cost > 0) {
      // Rough estimate: modifier * cost impact
      estimatedImprovement = Math.abs(modifier) * hourData.cost * 0.1;
      totalEstimatedImprovement += estimatedImprovement;
      improvementWeight += hourData.cost;
    }

    results.proposedModifiers.push({
      hour: h,
      hourLabel: formatHour(h),
      impressions: hourData.impressions,
      clicks: hourData.clicks,
      cost: hourData.cost,
      conversions: hourData.conversions,
      cpa: hourData.cpa,
      roas: hourData.roas,
      modifier: modifier,
      modifierPct: (modifier * 100).toFixed(0) + '%',
      canAdjust: canAdjust,
      reason: reason
    });
  }

  // Calculate estimated improvement
  if (results.summary.currentCPA > 0) {
    results.summary.estimatedCPAImprovement =
      (totalEstimatedImprovement / results.summary.totalCost) * 100 || 0;
  }

  // Sort by modifier impact
  results.proposedModifiers.sort(function(a, b) {
    return Math.abs(b.modifier) - Math.abs(a.modifier);
  });
}

function identifyBestWorstHours(results) {
  var sortedByPerformance = results.hourlyData.slice().sort(function(a, b) {
    if (CONFIG.TARGET_CPA > 0) {
      // Lower CPA is better
      var aCpa = a.cpa || 999999;
      var bCpa = b.cpa || 999999;
      return aCpa - bCpa;
    } else {
      // Higher ROAS is better
      return b.roas - a.roas;
    }
  });

  // Best hours (have conversions and good performance)
  results.summary.bestHours = sortedByPerformance
    .filter(function(h) { return h.conversions >= CONFIG.MIN_CONVERSIONS_FOR_ADJUSTMENT; })
    .slice(0, 5)
    .map(function(h) { return h.hourLabel; });

  // Worst hours
  results.summary.worstHours = sortedByPerformance
    .filter(function(h) { return h.conversions >= CONFIG.MIN_CONVERSIONS_FOR_ADJUSTMENT; })
    .slice(-5)
    .reverse()
    .map(function(h) { return h.hourLabel; });
}

/******************************************************************************
 * APPLY BID ADJUSTMENTS
 ******************************************************************************/
function applyBidAdjustments(results) {
  if (CONFIG.DRY_RUN) {
    log('INFO', '[DRY RUN] Would apply bid adjustments to ' + results.campaigns.length + ' campaigns');
    return;
  }

  log('INFO', 'Applying bid adjustments...');

  for (var i = 0; i < results.campaigns.length; i++) {
    var campaign = results.campaigns[i];

    try {
      var campaignObj = AdsApp.campaigns()
        .withCondition('CampaignId = ' + campaign.id)
        .get()
        .next();

      // Remove existing schedules if configured
      if (CONFIG.REMOVE_EXISTING_SCHEDULES) {
        var existingSchedules = campaignObj.targeting().adSchedules().get();
        while (existingSchedules.hasNext()) {
          existingSchedules.next().remove();
        }
      }

      // Apply new schedules
      var appliedCount = 0;

      for (var h = 0; h < results.proposedModifiers.length; h++) {
        var hourMod = results.proposedModifiers[h];

        if (!hourMod.canAdjust || hourMod.modifier === 0) continue;

        // Apply for all days of week
        for (var d = 0; d < DAYS.length; d++) {
          try {
            // Ad schedule format: MONDAY at 9:00 to 10:00 with +20% modifier
            campaignObj.addAdSchedule({
              dayOfWeek: DAYS[d],
              startHour: hourMod.hour,
              startMinute: 0,
              endHour: hourMod.hour === 23 ? 0 : hourMod.hour + 1,
              endMinute: 0,
              bidModifier: 1 + hourMod.modifier
            });
            appliedCount++;
          } catch (e) {
            log('DEBUG', 'Could not add schedule for ' + DAYS[d] + ' hour ' + hourMod.hour + ': ' + e.message);
          }
        }
      }

      results.appliedChanges.push({
        campaign: campaign.name,
        campaignId: campaign.id,
        schedulesApplied: appliedCount,
        status: 'SUCCESS'
      });

      results.summary.campaignsOptimized++;
      results.summary.modifiersApplied += appliedCount;

      log('INFO', 'Applied ' + appliedCount + ' schedules to ' + campaign.name);

    } catch (e) {
      log('WARN', 'Failed to apply adjustments to ' + campaign.name + ': ' + e.message);

      results.appliedChanges.push({
        campaign: campaign.name,
        campaignId: campaign.id,
        schedulesApplied: 0,
        status: 'ERROR: ' + e.message
      });
    }
  }
}

/******************************************************************************
 * OUTPUT FUNCTIONS
 ******************************************************************************/
function initializeSpreadsheet() {
  var ss;

  if (!CONFIG.SPREADSHEET_URL || CONFIG.SPREADSHEET_URL === 'YOUR_SPREADSHEET_URL_HERE' || CONFIG.SPREADSHEET_URL === 'CREATE_NEW') {
    ss = SpreadsheetApp.create('PPC.io Hourly Optimization - ' +
                               AdsApp.currentAccount().getName() + ' - ' +
                               formatDate(new Date()));
    log('INFO', 'Created spreadsheet: ' + ss.getUrl());
  } else {
    ss = SpreadsheetApp.openByUrl(CONFIG.SPREADSHEET_URL);
  }

  return ss;
}

function writeAllSheets(ss, results) {
  // 1. Summary
  writeSummarySheet(ss, results);

  // 2. Hourly Performance
  if (results.hourlyData.length > 0) {
    var hourlyOutput = results.hourlyData.map(function(h) {
      return {
        'Hour': h.hourLabel,
        'Impressions': h.impressions,
        'Clicks': h.clicks,
        'Cost': '$' + h.cost.toFixed(2),
        'Conversions': h.conversions.toFixed(2),
        'CTR': (h.ctr * 100).toFixed(2) + '%',
        'Conv Rate': (h.convRate * 100).toFixed(2) + '%',
        'CPA': h.cpa ? '$' + h.cpa.toFixed(2) : '-',
        'ROAS': h.roas.toFixed(2) + 'x'
      };
    });

    // Sort by hour
    hourlyOutput.sort(function(a, b) {
      return parseInt(a.Hour) - parseInt(b.Hour);
    });

    writeSheet(ss, '2. Hourly Performance', hourlyOutput,
      ['Hour', 'Impressions', 'Clicks', 'Cost', 'Conversions', 'CPA', 'ROAS', 'CTR']);
  }

  // 3. Proposed Modifiers
  if (results.proposedModifiers.length > 0) {
    var modifierOutput = results.proposedModifiers.map(function(m) {
      return {
        'Hour': m.hourLabel,
        'Proposed Modifier': m.modifierPct,
        'Can Adjust': m.canAdjust ? 'Yes' : 'No',
        'Reason': m.reason,
        'Cost': '$' + m.cost.toFixed(2),
        'Conversions': m.conversions.toFixed(2),
        'CPA': m.cpa ? '$' + m.cpa.toFixed(2) : '-',
        'ROAS': m.roas.toFixed(2) + 'x'
      };
    });

    // Sort by hour
    modifierOutput.sort(function(a, b) {
      return parseInt(a.Hour) - parseInt(b.Hour);
    });

    writeSheet(ss, '3. Proposed Modifiers', modifierOutput,
      ['Hour', 'Proposed Modifier', 'Can Adjust', 'Reason', 'Cost', 'CPA', 'ROAS']);
  }

  // 4. Applied Changes (if any)
  if (results.appliedChanges.length > 0) {
    var appliedOutput = results.appliedChanges.map(function(c) {
      return {
        'Campaign': c.campaign,
        'Schedules Applied': c.schedulesApplied,
        'Status': c.status
      };
    });
    writeSheet(ss, '4. Applied Changes', appliedOutput,
      ['Campaign', 'Schedules Applied', 'Status']);
  }

  // 5. Heatmap Data (hour x performance)
  writeHeatmapSheet(ss, results);
}

function writeHeatmapSheet(ss, results) {
  var sheet = ss.getSheetByName('5. Performance Heatmap');
  if (!sheet) {
    sheet = ss.insertSheet('5. Performance Heatmap');
  } else {
    sheet.clear();
  }

  // Create heatmap header
  var headers = ['Hour'];
  for (var h = 0; h < 24; h++) {
    headers.push(formatHour(h));
  }

  // Create rows for each metric
  var cpaRow = ['CPA'];
  var roasRow = ['ROAS'];
  var convRow = ['Conversions'];
  var modRow = ['Modifier'];

  for (var h = 0; h < 24; h++) {
    var hourData = results.hourlyData.find(function(d) { return d.hour === h; }) ||
                   { cpa: null, roas: 0, conversions: 0 };
    var modifier = results.proposedModifiers.find(function(m) { return m.hour === h; }) ||
                   { modifier: 0 };

    cpaRow.push(hourData.cpa ? '$' + hourData.cpa.toFixed(0) : '-');
    roasRow.push(hourData.roas.toFixed(1) + 'x');
    convRow.push(hourData.conversions.toFixed(0));
    modRow.push((modifier.modifier * 100).toFixed(0) + '%');
  }

  var data = [headers, cpaRow, roasRow, convRow, modRow];
  sheet.getRange(1, 1, data.length, data[0].length).setValues(data);
  sheet.getRange(1, 1, 1, data[0].length).setFontWeight('bold');

  // Apply color coding to modifier row
  for (var col = 2; col <= 25; col++) {
    var modValue = parseFloat(modRow[col - 1]) / 100;
    var color = '#ffffff';
    if (modValue > 0.2) color = '#d4edda';
    else if (modValue > 0) color = '#e8f5e9';
    else if (modValue < -0.2) color = '#f8d7da';
    else if (modValue < 0) color = '#ffebee';
    sheet.getRange(5, col).setBackground(color);
  }
}

